function stripHtml(html) {
  if (!html) return '';
  let text = html
    .replace(/<style[^>]*>[\s\S]*?<\/style>/gi, '')
    .replace(/<script[^>]*>[\s\S]*?<\/script>/gi, '')
    .replace(/<br\s*\/?>(\n)?/gi, '\n')
    .replace(/<\/p>/gi, '\n')
    .replace(/<[^>]+>/g, '')
    .replace(/&nbsp;/g, ' ')
    .replace(/&amp;/g, '&')
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&#39;/g, "'")
    .replace(/&quot;/g, '"');
  return text.trim();
}

function removeQuotedAndSignature(body) {
  if (!body) return '';
  let cleaned = body;

  // Cut off common "On ... wrote:" quoted-reply markers
  const quotePatterns = [
    /On .{0,80} wrote:[\s\S]*$/i,
    /-----Original Message-----[\s\S]*$/i,
    /From: .{0,120}\nSent: [\s\S]*$/i,
    /^>.*$/gm
  ];
  for (const pattern of quotePatterns) {
    cleaned = cleaned.split(pattern)[0];
  }

  // Cut off common signature delimiters
  const sigPatterns = [
    /\n--\s*\n[\s\S]*$/,
    /\nBest regards[\s\S]*$/i,
    /\nKind regards[\s\S]*$/i,
    /\nSent from my (iPhone|Android|Samsung)[\s\S]*$/i,
    /\nThanks,\s*\n[\s\S]*$/i
  ];
  for (const pattern of sigPatterns) {
    cleaned = cleaned.split(pattern)[0];
  }

  return cleaned.trim();
}

const out = [];

for (const item of $input.all()) {
  const j = item.json;

  const messageId = j.id || j.messageId || '';
  const threadId = j.threadId || '';
  const headers = j.headers || {};

  const subjectRaw = j.subject || headers.subject || '';
  const fromRaw = j.from || headers.from || '';

  // Parse "Name <email@x.com>" style sender
  let senderName = '';
  let senderEmail = '';
  const match = /^(.*)<(.+)>$/.exec(fromRaw.trim());
  if (match) {
    senderName = match[1].replace(/"/g, '').trim();
    senderEmail = match[2].trim();
  } else {
    senderEmail = fromRaw.trim();
  }
  if (!senderName) senderName = 'Unknown Sender';
  if (!senderEmail) senderEmail = 'unknown@unknown.com';

  const subject = subjectRaw && subjectRaw.trim() ? subjectRaw.trim() : '(No Subject)';

  let bodyRaw = j.text || j.html || j.snippet || '';
  if (!j.text && j.html) {
    bodyRaw = stripHtml(j.html);
  }
  let body = removeQuotedAndSignature(bodyRaw || '');
  if (!body) body = '(Empty email body)';

  const attachments = (j.attachments || []).map(a => ({
    filename: a.filename || 'attachment',
    mimeType: a.mimeType || 'unknown'
  }));

  out.push({
    json: {
      messageId,
      threadId,
      senderName,
      senderEmail,
      subject,
      body,
      receivedAt: j.date || new Date().toISOString(),
      hasAttachments: attachments.length > 0,
      attachments
    }
  });
}

return out;

