const CONFIDENCE_THRESHOLD = 0.75;
const out = [];

for (const item of $input.all()) {
  const emailData = item.json;
  let ai;

  try {
    const raw = emailData.message?.content ?? emailData.content ?? emailData.text ?? emailData.output ?? '{}';
    ai = typeof raw === 'string' ? JSON.parse(raw) : raw;
  } catch (err) {
    // AI failed to return valid JSON -> fail safe to HUMAN_REVIEW
    ai = {
      category: 'Other',
      intent: 'Unknown (AI parsing failed)',
      priority: 'Medium',
      isLead: false,
      responseRequired: true,
      summary: 'AI response could not be parsed.',
      confidence: 0,
      autoReplySafe: false,
      humanReviewRequired: true,
      reviewReason: 'AI output could not be parsed as JSON — routed to human review for safety.'
    };
  }

  // Enforce the hard safety rule: never trust a low-confidence AUTO_REPLY
  const confidence = typeof ai.confidence === 'number' ? ai.confidence : 0;
  let autoReplySafe = ai.autoReplySafe === true && confidence >= CONFIDENCE_THRESHOLD;
  let humanReviewRequired = ai.humanReviewRequired === true || !autoReplySafe;

  const decision = autoReplySafe && !humanReviewRequired ? 'AUTO_REPLY' : 'HUMAN_REVIEW';

  out.push({
    json: {
      ...emailData,
      category: ai.category || 'Other',
      intent: ai.intent || 'Unclear',
      priority: ai.priority || 'Medium',
      isLead: !!ai.isLead,
      responseRequired: ai.responseRequired !== false,
      summary: ai.summary || '',
      confidence,
      autoReplySafe,
      humanReviewRequired,
      reviewReason: ai.reviewReason || (decision === 'HUMAN_REVIEW' ? 'Did not meet auto-reply safety criteria.' : ''),
      decision,
      status: decision === 'AUTO_REPLY' ? 'Analyzing' : 'Human Review'
    }
  });
}

return out;

