const out = [];
for (const item of $input.all()) {
  const j = item.json;
  let reply;
  try {
    const raw = j.message?.content ?? j.content ?? j.text ?? '{}';
    reply = typeof raw === 'string' ? JSON.parse(raw) : raw;
  } catch (err) {
    reply = null;
  }

  if (!reply || !reply.body) {
    out.push({ json: { ...j, decision: 'HUMAN_REVIEW', status: 'Human Review', reviewReason: 'Reply generation failed — routed to human review for safety.', replySubject: '', replyBody: '' } });
  } else {
    out.push({ json: { ...j, replySubject: reply.subject || ('Re: ' + j.subject), replyBody: reply.body } });
  }
}
return out;

